-- Real catalogue, isolated actors, all test data rolled back. No network/production.
BEGIN;
GRANT USAGE ON SCHEMA public,auth TO authenticated;
CREATE FUNCTION suggestion_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF NOT coalesce(ok,false) THEN RAISE EXCEPTION 'FAIL: %',label; END IF;RAISE NOTICE 'PASS: %',label;END; $$;
CREATE FUNCTION suggestion_reject(command text,label text,expected text DEFAULT '42501') RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE command;EXCEPTION WHEN OTHERS THEN IF SQLSTATE<>expected THEN RAISE EXCEPTION 'FAIL wrong error % for %: %',SQLSTATE,label,SQLERRM;END IF;RAISE NOTICE 'PASS rejected: %',label;RETURN;END;RAISE EXCEPTION 'FAIL accepted: %',label;END; $$;
INSERT INTO auth.users(id,email) SELECT ('af200000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'suggestions-'||n||'@example.test' FROM generate_series(1,6)n;
INSERT INTO staff_users(id,auth_id,nom,email,role,actif) SELECT ('af210000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('af200000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Suggestion actor '||n,'suggestions-'||n||'@example.test','preparateur',n<>5 FROM generate_series(1,5)n;
INSERT INTO staff_permissions(staff_id,perm_colis_calculer_devis,perm_factures_voir,perm_factures_modifier_articles) SELECT ('af210000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,n IN(1,5),n=2,n=3 FROM generate_series(1,5)n;
-- Distinct fixture editions verify destination/reference scoping, NULL rates and ranking independent of tax.
INSERT INTO customs_tariffs(id,code,label,destination_code,om,omr,source_id,source_label,source_url,source_date,page,source_status) VALUES
('suggest-a','00999997','Objettest exclusif','974',18,2,'suggest-test','Fixture','https://example.test','2026-01-01',1,'reference'),
('suggest-b','00999997','Objettest exclusif','974',0,0,'suggest-test','Fixture','https://example.test','2026-01-01',1,'reference'),
('suggest-c','00999997','Objettest exclusif','974',NULL,NULL,'suggest-test','Fixture','https://example.test','2026-01-01',1,'reference'),
('suggest-old','00999997','Objettest exclusif','974',0,0,'suggest-test','Fixture','https://example.test','2025-01-01',1,'historical'),
('suggest-else','00999997','Objettest exclusif','972',0,0,'suggest-test','Fixture','https://example.test','2026-01-01',1,'reference');
CREATE TEMP TABLE suggestion_baseline AS SELECT
 (SELECT md5(string_agg(to_jsonb(t)::text,'|' ORDER BY id)) FROM customs_tariffs t) tariffs,
 (SELECT md5(coalesce(string_agg(to_jsonb(t)::text,'|' ORDER BY id),'')) FROM lignes t) articles,
 (SELECT count(*) FROM audit_actions) audit_count,(SELECT count(*) FROM notification_outbox) outbox_count;
SELECT suggestion_assert(NOT has_function_privilege('anon','suggest_customs_tariffs(jsonb,text)','EXECUTE'),'anonymous execute denied');
SELECT suggestion_assert(NOT has_function_privilege('service_role','suggest_customs_tariffs(jsonb,text)','EXECUTE'),'service role not granted suggestion RPC');
SELECT suggestion_assert(NOT has_function_privilege('authenticated','customs_commercial_terms(text)','EXECUTE'),'private lexical helpers not exposed');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.role','authenticated',true);
SELECT set_config('request.jwt.claim.sub','af200000-0000-4000-8000-000000000004',true);
SELECT suggestion_reject($q$SELECT suggest_customs_tariffs('[{"lineId":"x","description":"smartphone"}]','974')$q$,'actor 4: no permission, inactive or client denied');
SELECT set_config('request.jwt.claim.sub','af200000-0000-4000-8000-000000000005',true);
SELECT suggestion_reject($q$SELECT suggest_customs_tariffs('[{"lineId":"x","description":"smartphone"}]','974')$q$,'actor 5: no permission, inactive or client denied');
SELECT set_config('request.jwt.claim.sub','af200000-0000-4000-8000-000000000006',true);
SELECT suggestion_reject($q$SELECT suggest_customs_tariffs('[{"lineId":"x","description":"smartphone"}]','974')$q$,'actor 6: no permission, inactive or client denied');
SELECT set_config('request.jwt.claim.sub','af200000-0000-4000-8000-000000000001',true);
SELECT suggestion_assert(jsonb_array_length(suggest_customs_tariffs('[{"lineId":"x","description":"smartphone"}]','974')->0->'candidates')>0,'isolated permission 1 permits read-only suggestions');
SELECT set_config('request.jwt.claim.sub','af200000-0000-4000-8000-000000000002',true);
SELECT suggestion_assert(jsonb_array_length(suggest_customs_tariffs('[{"lineId":"x","description":"smartphone"}]','974')->0->'candidates')>0,'isolated permission 2 permits read-only suggestions');
SELECT set_config('request.jwt.claim.sub','af200000-0000-4000-8000-000000000003',true);
SELECT suggestion_assert(jsonb_array_length(suggest_customs_tariffs('[{"lineId":"x","description":"smartphone"}]','974')->0->'candidates')>0,'isolated permission 3 permits read-only suggestions');
SELECT suggestion_reject($q$SELECT suggest_customs_tariffs(NULL,'974')$q$,'NULL batch','22023');
SELECT suggestion_reject($q$SELECT suggest_customs_tariffs('{}','974')$q$,'object batch','22023');
SELECT suggestion_reject($q$SELECT suggest_customs_tariffs('[]','974')$q$,'empty batch','22023');
SELECT suggestion_reject($q$SELECT suggest_customs_tariffs('[{}]','974')$q$,'missing fields','22023');
SELECT suggestion_reject($q$SELECT suggest_customs_tariffs('[null]','974')$q$,'null item','22023');
SELECT suggestion_reject($q$SELECT suggest_customs_tariffs('[{"lineId":"x","description":17}]','974')$q$,'nontext description','22023');
SELECT suggestion_reject($q$SELECT suggest_customs_tariffs('[{"lineId":"x","description":"shirt"},{"lineId":"x","description":"shirt"}]','974')$q$,'duplicate line IDs','22023');
SELECT suggestion_reject($q$SELECT suggest_customs_tariffs('[{"lineId":"x","description":"shirt"}]',NULL)$q$,'null destination','22023');
SELECT suggestion_reject($q$SELECT suggest_customs_tariffs('[{"lineId":"x","description":"shirt"}]','XXX')$q$,'unknown destination','22023');
SELECT suggestion_reject($q$SELECT suggest_customs_tariffs(jsonb_build_array(jsonb_build_object('lineId','x','description',repeat('x',2001))),'974')$q$,'overlong description','22023');
SELECT suggestion_reject($q$SELECT suggest_customs_tariffs((SELECT jsonb_agg(jsonb_build_object('lineId',n::text,'description','shirt')) FROM generate_series(1,51)n),'974')$q$,'batch over 50','22023');
CREATE TEMP TABLE suggestion_results AS SELECT value result FROM jsonb_array_elements(suggest_customs_tariffs('[{"lineId": "tee", "description": "T-shirt homme 100% coton"}, {"lineId": "socks", "description": "Lot de 3 chaussettes sport coton"}, {"lineId": "dress", "description": "Robe femme polyester"}, {"lineId": "jean", "description": "Jean femme denim coton taille 38"}, {"lineId": "shoes", "description": "Baskets femme semelle caoutchouc dessus textile"}, {"lineId": "sandals", "description": "Sandales cuir enfant pointure 28"}, {"lineId": "sealer", "description": "Mini scelleuse thermique rechargeable USB"}, {"lineId": "sink", "description": "Organiseur évier ABS avec égouttoir"}, {"lineId": "phone", "description": "iPhone 15 smartphone 128 Go"}, {"lineId": "case", "description": "Coque silicone pour iPhone 15"}, {"lineId": "charger", "description": "Chargeur USB-C 65W rapide"}, {"lineId": "earbuds", "description": "Écouteurs Bluetooth sans fil"}, {"lineId": "lamp", "description": "Lampe de bureau LED rechargeable"}, {"lineId": "sunscreen", "description": "Crème solaire SPF 50 non teintée non parfumée"}, {"lineId": "cream", "description": "Crème hydratante visage 50 ml"}, {"lineId": "coffee", "description": "Café torréfié moulu 250g"}, {"lineId": "box", "description": "Boîte conservation alimentaire plastique 1 litre"}, {"lineId": "bottle", "description": "Gourde inox isotherme 500ml"}, {"lineId": "vague", "description": "Accessoire maison"}, {"lineId": "mixed", "description": "Lot divers cadeaux : t-shirt, jouet et coque téléphone"}, {"lineId": "casePhone", "description": "Coque pour smartphone"}, {"lineId": "chargerPhone", "description": "Chargeur pour smartphone"}, {"lineId": "screenPhone", "description": "Écran de remplacement pour iPhone 15"}, {"lineId": "cream30", "description": "Crème solaire SPF30"}, {"lineId": "creamTinted", "description": "Crème solaire SPF50 teintée et parfumée", "categoryCode": "8517"}, {"lineId": "coffeeRaw", "description": "Café non torréfié"}, {"lineId": "coffeeDecaf", "description": "Café torréfié décaféiné moulu"}, {"lineId": "shirtLot", "description": "Lot de 3 T-shirts coton"}, {"lineId": "mixedSimple", "description": "T-shirt coton, baskets et jouet"}, {"lineId": "mixedSimple2", "description": "T-shirt et coque pour téléphone"}, {"lineId": "vagueBrand", "description": "Samsung"}, {"lineId": "vagueCode", "description": "Article"}, {"lineId": "battery", "description": "Batterie externe powerbank 10000mAh"}, {"lineId": "sealerBags", "description": "Mini thermoscelleuse pour sachets plastiques"}, {"lineId": "phoneAccessory", "description": "Smartphone avec coque"}, {"lineId": "screenNoPhone", "description": "Écran de remplacement"}, {"lineId": "book", "description": "Roman livre en français"}, {"lineId": "soap", "description": "Savon solide parfumé 100g"}, {"lineId": "toothpaste", "description": "Dentifrice menthe 75ml"}, {"lineId": "shampoo", "description": "Shampoing cheveux secs 250ml"}, {"lineId": "abs", "description": "ABS", "categoryCode": "85"}, {"lineId": "generic", "description": "produit article accessoire", "categoryCode": "85171300"}, {"lineId": "mixedEt", "description": "T-shirt coton et baskets textile"}, {"lineId": "unknown", "description": "Marqueintrouvable modèle 123"}, {"lineId": "empty", "description": ""}]','974'));
SELECT suggestion_assert((SELECT count(*)=45 AND count(DISTINCT result->>'lineId')=45 FROM suggestion_results),'one response per original input including abstentions');
SELECT suggestion_assert((SELECT bool_and(jsonb_array_length(result->'candidates')<=5 AND result->>'requiresReview'='true') FROM suggestion_results),'bounded results require review without invented confidence');
SELECT suggestion_assert((SELECT bool_and(NOT(value ? 'confidence') AND NOT(value ? 'suggestion_vector') AND length(value->>'matchReason')>0) FROM suggestion_results CROSS JOIN LATERAL jsonb_array_elements(result->'candidates')),'only public reference fields and understandable match reason');
