CREATE TEMP TABLE suggestion_fixture AS SELECT suggest_customs_tariffs('[{"lineId":"fixture","description":"Objettest exclusif"}]','974')->0->'candidates' candidates;
SELECT suggestion_assert((SELECT jsonb_array_length(candidates)=3 AND candidates#>>'{0,id}'='suggest-a' AND candidates#>>'{1,id}'='suggest-b' AND candidates#>>'{2,id}'='suggest-c' FROM suggestion_fixture),'same-code variants remain separate, destination/history filtered, zero rate not favored');
SELECT suggestion_assert((SELECT candidates#>'{2,om}'='null'::jsonb AND candidates#>'{2,omr}'='null'::jsonb FROM suggestion_fixture),'ambiguous reference rates remain NULL rather than invented zero');
SELECT suggestion_assert(suggest_customs_tariffs('[{"lineId":"fixture","description":"Objettest exclusif"}]','974')->0->'candidates'=(SELECT candidates FROM suggestion_fixture),'stable deterministic ordering on repeat');
