RESET ROLE;
SELECT suggestion_assert(NOT EXISTS(SELECT 1 FROM suggestion_results CROSS JOIN LATERAL jsonb_array_elements(result->'candidates') c LEFT JOIN customs_tariffs t ON t.id=c->>'id' WHERE t.id IS NULL OR c->>'code'<>t.code OR c->>'label'<>t.label OR c->'om' IS DISTINCT FROM to_jsonb(t.om) OR c->'omr' IS DISTINCT FROM to_jsonb(t.omr) OR c->>'source_url'<>t.source_url),'every suggested code, label, external rate and source comes unchanged from reference');
SELECT suggestion_assert((SELECT tariffs=(SELECT md5(string_agg(to_jsonb(t)::text,'|' ORDER BY id)) FROM customs_tariffs t) AND articles=(SELECT md5(coalesce(string_agg(to_jsonb(t)::text,'|' ORDER BY id),'')) FROM lignes t) AND audit_count=(SELECT count(*) FROM audit_actions) AND outbox_count=(SELECT count(*) FROM notification_outbox) FROM suggestion_baseline),'suggesting makes no catalogue, article, audit or notification writes');
SET LOCAL ROLE authenticated;
-- Measured performance only; avoid a timing-sensitive CI assertion.
EXPLAIN (ANALYZE,BUFFERS) SELECT suggest_customs_tariffs((SELECT jsonb_agg(jsonb_build_object('lineId',n::text,'description',CASE n%5 WHEN 0 THEN 'T-shirt homme coton' WHEN 1 THEN 'Smartphone iPhone 15' WHEN 2 THEN 'Savon solide parfumé' WHEN 3 THEN 'Crème solaire SPF50 non teintée non parfumée' ELSE 'Mini scelleuse thermique rechargeable' END)) FROM generate_series(1,50)n),'974');
ROLLBACK;
